<?php require 'config.php';need('buyer');$title='Mis pedidos';
$s=$pdo->prepare('SELECT o.id,o.created_at,oi.qty,oi.price,oi.status,p.id pid,p.name FROM orders o JOIN order_items oi ON oi.order_id=o.id JOIN products p ON p.id=oi.product_id WHERE o.user_id=? ORDER BY o.id DESC');$s->execute([user()['id']]);$r=$s->fetchAll();include 'header.php';?>
<h1>Mis pedidos</h1><?php if(!$r):?><p class="muted">Aún no compraste nada. <a href="index.php">Ver catálogo</a></p><?php endif;?><table><?php foreach($r as $x):?><tr><td>#<?=$x['id']?></td><td><a href="product.php?id=<?=$x['pid']?>"><?=e($x['name'])?></a> × <?=$x['qty']?></td><td><?=money($x['price']*$x['qty'])?></td><td><span class="tag <?=$x['status']?>"><?=$x['status']?></span></td></tr><?php endforeach;?></table><?php include 'footer.php';?>
